{"cards": [{"node_code": "N_3f938a72b19e0f85", "definition": "研究脊髓灰质炎病毒（Poliovirus）的生物学特性、致病机制、免疫原性及实验室诊断，重点探讨其引起小儿麻痹症的神经毒性与疫苗预防策略。", "boundary": "本节点专指脊髓灰质炎病毒。涵盖病毒在肠道复制、经血行播散至脊髓前角运动神经元的机制，以及灭活（IPV）和减毒（OPV）疫苗的作用原理。与柯萨奇病毒的区别在于靶器官特异性（脊髓运动神经元 vs 多系统）及主要临床后果（弛缓性瘫痪 vs 心肌炎/疱疹性咽峡炎等）。", "includes": ["脊髓灰质炎病毒的分类、结构及复制周期", "病毒神经毒性与小儿麻痹症发病机制", "脊髓灰质炎疫苗（IPV/OPV）的免疫学基础与监测"], "excludes": ["其他肠道病毒引起的神经系统疾病（归入相应病毒节点）", "脊髓灰质炎的临床康复与物理治疗（归入康复医学或神经病学）"], "sibling_distinctions": [{"other_code": "N_461e8d7aba8cda9b", "rule": "脊髓灰质炎病毒主要侵犯脊髓前角运动神经元导致弛缓性瘫痪；柯萨奇病毒虽也可致神经系统症状，但更常引起心肌炎、手足口病或无菌性脑膜炎，且血清型分布不同。"}, {"other_code": "N_1a80414d9262eea1", "rule": "脊髓灰质炎病毒是独立的病毒种，具有特定的神经嗜性；埃可病毒与其他肠道病毒主要引起无症状感染或轻微症状，神经侵袭性相对较低且血清型众多。"}], "cross_boundary_rule": "若内容涉及脊髓灰质炎病毒的全球根除策略、疫苗安全性监测或病毒基因型演化，归入本节点；若重点在于已发生瘫痪患者的临床护理或康复训练，则关联临床康复或神经科。"}, {"node_code": "N_461e8d7aba8cda9b", "definition": "研究柯萨奇病毒（Coxsackievirus）A组和B组的生物学特性、致病机制及诊断，涵盖其引起的心肌炎、手足口病、疱疹性咽峡炎及神经系统感染。", "boundary": "本节点专指柯萨奇病毒。涵盖病毒在肠道感染后经血行播散至心肌、皮肤、黏膜及神经系统的机制。与脊髓灰质炎病毒的区别在于柯萨奇病毒血清型更多，致病谱更广（尤其心肌炎和手足口病）；与埃可病毒的区别在于柯萨奇病毒引起典型临床综合征（如手足口病）的比例更高。", "includes": ["柯萨奇病毒A组与B组的分类、血清型及生物学特性", "柯萨奇病毒引起的心肌炎、心包炎及手足口病机制", "柯萨奇病毒相关的无菌性脑膜炎及实验室诊断"], "excludes": ["由肠道病毒71型（EV71）引起的手足口病重症（若树中有EV71独立节点则归入，否则常归入本节点或埃可与其他，需视具体分类粒度，此处暂归入本节点或埃可与其他，鉴于EV71常与柯萨奇并列讨论，若无独立节点，需确认。通常EV71归入肠道病毒属，若树中无EV71独立节点，可能归入“埃可病毒与其他”或“柯萨奇”。根据常见分类，EV71常单独列出或归入肠道病毒其他。此处假设EV71归入“埃可病毒与其他”或需确认。为安全起见，本节点聚焦经典柯萨奇A/B组。若EV71无独立节点，通常与柯萨奇病毒在临床手足口病中关联紧密，但生物学上EV71是独立种。若树中无EV71，建议归入“埃可病毒与其他肠道病毒”或需确认。此处按经典柯萨奇病毒定义。", "其他肠道病毒引起的非特异性发热（归入埃可病毒与其他）"], "sibling_distinctions": [{"other_code": "N_3f938a72b19e0f85", "rule": "柯萨奇病毒致病谱广，常见心肌炎、手足口病；脊髓灰质炎病毒特异性强，主要导致弛缓性瘫痪。"}, {"other_code": "N_1a80414d9262eea1", "rule": "柯萨奇病毒有明确的A/B组分类及典型临床综合征（如手足口病）；埃可病毒多无症状或轻微，其他肠道病毒（如EV71、诺如等）若未单列则在此，但柯萨奇病毒特指Coxsackievirus属。"}], "cross_boundary_rule": "若内容涉及柯萨奇病毒引起的心肌炎病理机制或病毒分离鉴定，归入本节点；若重点在于手足口病的临床分型治疗（特别是重症EV71感染，若EV71归入其他节点），则需根据EV71的归属调整。若EV71归入“埃可病毒与其他”，则本节点不包含EV71。"}, {"node_code": "N_1a80414d9262eea1", "definition": "研究埃可病毒（Echovirus）及其他未单列的肠道病毒（如肠道病毒71型、诺如病毒、轮状病毒等）的生物学特性、致病机制及诊断方法。", "boundary": "本节点涵盖埃可病毒及肠道病毒属中除脊髓灰质炎病毒、柯萨奇病毒外的其他成员，包括肠道病毒71型（EV71）、肠道病毒68型等，以及杯状病毒（诺如）、呼肠病毒（轮状）等经肠道传播的病毒。与柯萨奇病毒的区别在于埃可病毒多引起无症状感染或轻微症状，而其他肠道病毒如EV71是手足口病重症的主要病原。", "includes": ["埃可病毒的分类、血清型及致病特点", "肠道病毒71型（EV71）等新型肠道病毒的生物学与致病性", "诺如病毒、轮状病毒等非肠道病毒属但经肠道传播的病毒特性"], "excludes": ["脊髓灰质炎病毒（归入脊髓灰质炎病毒节点）", "柯萨奇病毒A/B组（归入柯萨奇病毒节点）"], "sibling_distinctions": [{"other_code": "N_3f938a72b19e0f85", "rule": "埃可病毒与其他肠道病毒不包括脊髓灰质炎病毒，后者有独立的神经毒性和疫苗体系。"}, {"other_code": "N_461e8d7aba8cda9b", "rule": "本节点包含埃可病毒及EV71等，不包括经典的柯萨奇病毒A/B组；EV71虽与柯萨奇病毒同属肠道病毒属，但常因致病性（重症手足口病）单独关注，若树中无EV71独立节点，通常归入此类“其他”或需确认。此处将EV71归入本节点以覆盖手足口病重症病原。"}], "cross_boundary_rule": "若内容涉及埃可病毒的无症状感染特征或EV71引起的手足口病重症机制，归入本节点；若涉及诺如病毒引起的流行性胃肠炎防控，亦归入本节点（因诺如病毒常归入肠道病毒大类下的其他病毒）。"}]}
